import AppKit

/// Decides what to record from a pasteboard snapshot. Pure apart from RTF parsing.
enum CapturePolicy {
  /// Any of these anywhere on the pasteboard means "do not record" (http://nspasteboard.org plus Maccy's defaults).
  static let ignoredTypes: Set<String> = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "Pasteboard generator type",
    "com.agilebits.onepassword",
    "com.typeit4me.clipping",
    "de.petermaurer.TransientPasteboardType",
    "net.antelle.keeweb",
  ]

  /// Metadata that is volatile or privacy-revealing and never needed to paste.
  static let droppedTypes: Set<String> = [
    "org.chromium.source-url",
    "org.chromium.internal.source-rfh-token",
    "org.nspasteboard.source",
    "com.apple.linkpresentation.metadata",
    "com.apple.WebKit.custom-pasteboard-data",
    "x.nspasteboard.ModifiedType",
    "com.apple.webarchive", // Safari's page archive embeds the source URL; HTML/RTF still paste
  ]
  static let droppedPrefixes = ["dyn.", "com.microsoft.ole.source."]

  /// Read first so they win the per-item byte budget over app-specific formats.
  static let coreTypes: [String] = [
    PBType.fileURL, PBType.string, PBType.rtf, PBType.html, PBType.png, PBType.tiff,
    PBType.jpeg, PBType.heic, PBType.rtfd,
  ]

  static func shouldIgnore(types: [String]) -> Bool {
    types.contains(where: ignoredTypes.contains)
  }

  static func isDropped(_ type: String) -> Bool {
    droppedTypes.contains(type) || droppedPrefixes.contains(where: type.hasPrefix)
  }

  /// Merges all pasteboard items into one entry (some apps write several), keeping pasteboard order.
  /// File URLs are kept per item; other types only once. `read(itemIndex, type)` is never called for dropped
  /// types, and reading stops at the first type that exceeds the remaining budget (NSPasteboard cannot report
  /// a size before reading, so that one oversized type is read once and discarded).
  static func collect(itemTypes: [[String]], budget: Int = Limits.maxItemBytes,
                      read: (Int, String) -> Data?) -> [ClipContent] {
    struct Slot { let item: Int; let type: String; let order: Int }
    var slots: [Slot] = []
    var seen = Set<String>()
    var order = 0
    for (i, types) in itemTypes.enumerated() {
      for t in types where !isDropped(t) {
        if t != PBType.fileURL {
          if seen.contains(t) { continue }
          seen.insert(t)
        }
        slots.append(Slot(item: i, type: t, order: order))
        order += 1
      }
    }
    let rank = { (t: String) in coreTypes.firstIndex(of: t) ?? coreTypes.count }
    let byPriority = slots.sorted { (rank($0.type), $0.order) < (rank($1.type), $1.order) }

    var remaining = budget
    var kept: [(Int, ClipContent)] = []
    for slot in byPriority where remaining > 0 {
      guard let data = read(slot.item, slot.type), !data.isEmpty else { continue }
      // Stop at the first type that does not fit, so a huge copy costs at most one wasted read.
      guard data.count <= remaining else { break }
      remaining -= data.count
      kept.append((slot.order, ClipContent(type: slot.type, data: data)))
    }
    return kept.sorted { $0.0 < $1.0 }.map(\.1)
  }

  static func makeItem(contents: [ClipContent], application: String?, now: Date) -> ClipItem? {
    let data = { (t: String) in contents.first { $0.type == t }?.data }
    let fileURLs = contents.filter { $0.type == PBType.fileURL }
      .compactMap { URL(dataRepresentation: $0.data, relativeTo: nil, isAbsolute: true) }
    let hasImage = PBType.imageTypes.contains { data($0) != nil }
    let plainData = data(PBType.string)
    let plain = plainData.flatMap { isASCIIWhitespace($0) ? nil : String(data: $0, encoding: .utf8) } ?? ""

    let kind: ClipKind
    var text: String
    if !fileURLs.isEmpty {
      kind = .files
      text = fileURLs.map { $0.absoluteString.removingPercentEncoding ?? $0.absoluteString }.joined(separator: "\n")
    } else if !isBlank(plain) {
      kind = .text
      text = plain
    } else if hasImage {
      kind = .image
      text = ""
    } else {
      kind = .text
      text = richText(rtf: data(PBType.rtf), html: data(PBType.html))
      if isBlank(text) { return nil }
    }

    return ClipItem(
      contents: contents, kind: kind, application: application,
      title: displayTitle(text), previewText: previewText(text), now: now)
  }

  /// Maccy's "show special symbols": visible edge spaces, ⏎ for newlines, ⇥ for tabs.
  static func displayTitle(_ text: String) -> String {
    var title = prefixScalars(text, Limits.titleLength)
    if let r = title.range(of: "^ +", options: .regularExpression) {
      title.replaceSubrange(r, with: String(repeating: "·", count: title.distance(from: r.lowerBound, to: r.upperBound)))
    }
    if let r = title.range(of: " +$", options: .regularExpression) {
      title.replaceSubrange(r, with: String(repeating: "·", count: title.distance(from: r.lowerBound, to: r.upperBound)))
    }
    return title
      .replacingOccurrences(of: "\r\n", with: "⏎")
      .replacingOccurrences(of: "\n", with: "⏎")
      .replacingOccurrences(of: "\r", with: "⏎")
      .replacingOccurrences(of: "\t", with: "⇥")
  }

  /// HTML is deliberately not handed to NSAttributedString: its importer runs WebKit and can load remote resources.
  static func richText(rtf: Data?, html: Data?) -> String {
    // Size caps keep title extraction cheap on the main thread; the full data is still pasted.
    if let rtf, rtf.count <= 1_000_000, let s = NSAttributedString(rtf: rtf, documentAttributes: nil)?.string, !isBlank(s) {
      return s
    }
    guard let html else { return "" }
    let head = html.prefix(64 * 1024)
    // Lenient decode: the 64 KB cut can split a multi-byte character, which would fail a strict decode.
    return stripTags(String(decoding: head, as: UTF8.self))
  }

  /// One forward pass over the bytes: every search starts where the previous one ended, so hostile input
  /// (thousands of `<`, unclosed or repeated script blocks) stays linear.
  static func stripTags(_ html: String) -> String {
    let b = Array(html.utf8)
    var out: [UInt8] = []
    out.reserveCapacity(b.count)
    let lt = UInt8(ascii: "<"), gt = UInt8(ascii: ">"), slash = UInt8(ascii: "/")
    func lower(_ c: UInt8) -> UInt8 { c >= 65 && c <= 90 ? c + 32 : c }
    func find(_ needle: [UInt8], from start: Int) -> Int? {
      var k = start
      while k + needle.count <= b.count {
        if lower(b[k]) == needle[0], (1..<needle.count).allSatisfy({ lower(b[k + $0]) == needle[$0] }) { return k }
        k += 1
      }
      return nil
    }
    /// `</tag` followed by `>`, `/` or whitespace, so `</scripts>` does not close `<script>`.
    func findClosing(_ tag: String, from start: Int) -> Int? {
      let needle = Array("</\(tag)".utf8)
      var from = start
      while let k = find(needle, from: from) {
        let after = k + needle.count
        if after >= b.count || [gt, slash, 0x20, 0x09, 0x0A, 0x0D].contains(b[after]) { return k }
        from = k + 1
      }
      return nil
    }
    var i = 0
    while i < b.count {
      guard b[i] == lt else {
        out.append(b[i])
        i += 1
        continue
      }
      // A '<' not followed by a tag start ("1 < 2") is plain text.
      let next = i + 1 < b.count ? lower(b[i + 1]) : 0
      guard (next >= 97 && next <= 122) || next == slash || next == UInt8(ascii: "!") else {
        out.append(b[i])
        i += 1
        continue
      }
      guard let close = find([gt], from: i + 1) else { break } // no '>' left: the rest is an unfinished tag
      let isClosing = i + 1 < b.count && b[i + 1] == slash
      var j = isClosing ? i + 2 : i + 1
      var name: [UInt8] = []
      while j < close {
        let c = lower(b[j])
        guard (c >= 97 && c <= 122) || (c >= 48 && c <= 57) else { break }
        name.append(c)
        j += 1
      }
      let tag = String(decoding: name, as: UTF8.self)
      if !isClosing, tag == "script" || tag == "style" {
        guard let end = findClosing(tag, from: close + 1), let endGT = find([gt], from: end) else { break }
        i = endGT + 1
        continue
      }
      if tag == "br" || (isClosing && ["p", "div", "li", "tr"].contains(tag)) { out.append(UInt8(ascii: "\n")) }
      i = close + 1
    }
    var s = String(decoding: out, as: UTF8.self)
    for (entity, char) in [("&nbsp;", " "), ("&lt;", "<"), ("&gt;", ">"), ("&quot;", "\""), ("&#39;", "'"), ("&amp;", "&")] {
      s = s.replacingOccurrences(of: entity, with: char)
    }
    return s.trimmingCharacters(in: .whitespacesAndNewlines)
  }

  /// Marks a cut preview so content hidden past the limit is not mistaken for the whole copy.
  static func previewText(_ text: String) -> String {
    let preview = prefixScalars(text, Limits.previewLength)
    return text.unicodeScalars.dropFirst(Limits.previewLength).isEmpty ? preview : preview + "\n…"
  }

  /// Caps by Unicode scalars, not Characters: one Character can hold millions of combining marks.
  static func prefixScalars(_ s: String, _ n: Int) -> String {
    String(String.UnicodeScalarView(s.unicodeScalars.prefix(n)))
  }

  /// Byte-level fast path so a huge whitespace-only copy is rejected without decoding it.
  static func isASCIIWhitespace(_ data: Data) -> Bool {
    data.withUnsafeBytes { bytes in
      !bytes.contains { $0 != 0x20 && $0 != 0x09 && $0 != 0x0A && $0 != 0x0D }
    }
  }

  /// Scalar scan with early exit: grapheme iteration is slow on 16 MB inputs and treats " " + combining marks as blank.
  static func isBlank(_ s: String) -> Bool {
    !s.unicodeScalars.contains { !$0.properties.isWhitespace }
  }
}
